export function classifyByHeuristic(statement, introOrdinals) {
    const heading = statement.enclosingHeading;
    const category = introOrdinals.has(statement.ordinal)
        ? "intro"
        : (matchRuleCategory(CONTENT_RULES, statement.text) ??
