        return {} as T;
      },
    };
    const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
    const rejection = await orchestrator.processMessage(createSession('hello')).catch((v: unknown) => v);
    expect({rejection, onErrorCalled}).toEqual({rejection: 'thrown string', onErrorCalled: false});
  });
});

